function sql(value) {
  if (value === undefined || value === null || String(value).trim() === '') return 'NULL';
  return "'" + String(value).replace(/'/g, "''") + "'";
}

function parseMaybeJson(value) {
  if (typeof value !== 'string') return value;
  try { return JSON.parse(value); } catch { return value; }
}
function requestBody(input) {
  const source = input && typeof input === 'object' ? input : {};
  const candidates = [source.body, parseMaybeJson(source.body), source.data, parseMaybeJson(source.data), source, parseMaybeJson(source.json)];
  for (const candidate of candidates) {
    if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) continue;
    if (candidate.publicationJobId || candidate.publication_job_id || candidate.brief || candidate.briefFeedback) return candidate;
  }
  return source;
}
const body = requestBody($json);
const publicationJobId = String(body.publicationJobId || body.publication_job_id || '').trim();
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (!uuidRegex.test(publicationJobId)) {
  return [{ json: { query: "SELECT false AS ok, 'publicationJobId is required' AS error;" } }];
}

const manualBrief = body.brief && typeof body.brief === 'object' ? body.brief : null;
const briefFeedback = body.briefFeedback && typeof body.briefFeedback === 'object' ? body.briefFeedback : null;
const query = `
SELECT
  true AS ok,
  pj.publication_job_id AS "publicationJobId",
  pj.avatar,
  pj.scene,
  pj.format,
  pj.objective,
  pj.business_profile AS "businessProfile",
  pj.asset_type AS "assetType",
  pj.status,
  pj.brief,
  pj.created_at AS "createdAt",
  pj.updated_at AS "updatedAt",
  ac.display_name AS "avatarDisplayName",
  ac.avatar_short AS "avatarShort",
  sc.display_name AS "sceneDisplayName",
  COALESCE(sc.description, '') AS "sceneDescription",
  COALESCE(sb.visual_intent, '') AS "sceneVisualIntent",
  COALESCE(sb.allowed_mood, '') AS "sceneAllowedMood",
  COALESCE(sb.content_angle, '') AS "sceneContentAngle",
  COALESCE(sb.prompt_notes, '') AS "scenePromptNotes",
  ${sql(JSON.stringify(manualBrief))}::jsonb AS "manualBrief",
  ${sql(JSON.stringify(briefFeedback))}::jsonb AS "briefFeedback",
  pj.metadata AS "jobMetadata"
FROM publication_jobs pj
LEFT JOIN avatar_catalog ac ON ac.avatar = pj.avatar
LEFT JOIN scene_catalog sc ON sc.avatar = pj.avatar AND sc.scene = pj.scene
LEFT JOIN scene_brief_catalog sb ON sb.avatar = pj.avatar AND sb.scene = pj.scene
WHERE pj.publication_job_id = ${sql(publicationJobId)}::uuid
LIMIT 1;
`;

return [{ json: { query } }];

function sql(value) {
  if (value === undefined || value === null || String(value).trim() === '') return 'NULL';
  return "'" + String(value).replace(/'/g, "''") + "'";
}
function sqlJson(value) {
  return sql(JSON.stringify(value ?? {})) + '::jsonb';
}
function toArray(value, fallback = []) {
  if (Array.isArray(value)) return value.map(String).filter(Boolean);
  if (typeof value === 'string' && value.trim()) return value.split(/[,;\n]/).map((x) => x.trim()).filter(Boolean);
  return fallback;
}
function normalizeBrief(raw, row) {
  const source = raw && typeof raw === 'object' ? raw : {};
  const fallbackVisualIntent = `${row.avatarDisplayName || row.avatar} in ${row.sceneDisplayName || row.scene}`;
  return {
    visualIntent: String(source.visualIntent || source.visual_intent || row.sceneVisualIntent || row.sceneDescription || fallbackVisualIntent).trim(),
    captionAngle: String(source.captionAngle || source.caption_angle || row.sceneContentAngle || row.objective).trim(),
    emotionalTone: String(source.emotionalTone || source.emotional_tone || row.sceneAllowedMood || 'natural, warm, authentic, lightly aspirational').trim(),
    avoidRules: toArray(source.avoidRules || source.avoid_rules, [
      'No luxury obsession or billionaire cues',
      'No motivational poster tone',
      'No overproduced influencer copy',
      'No artificial sadness or excessive drama',
      'No inconsistent facial identity or body exaggeration'
    ]),
    suggestedFormat: String(source.suggestedFormat || source.suggested_format || row.format).trim(),
    contentPillars: toArray(source.contentPillars || source.content_pillars, ['lifestyle', 'travel', 'wellness', 'social life', 'personal thoughts']),
    sceneNotes: String(source.sceneNotes || source.scene_notes || row.scenePromptNotes || '').trim(),
    captionSeeds: toArray(source.captionSeeds || source.caption_seeds, []),
    generationNotes: String(source.generationNotes || source.generation_notes || '').trim(),
  };
}

const row = $input.first()?.json || {};
if (row.ok === false || row.ok === 'f' || !row.publicationJobId) {
  const error = row.error || 'Publication job not found';
  return [{ json: { query: `SELECT false AS ok, ${sql(error)} AS error;` } }];
}

let brief;
let provider = 'manual';
let providerMeta = {};
const manualBrief = row.manualBrief && typeof row.manualBrief === 'object' ? row.manualBrief : null;
const briefFeedback = row.briefFeedback && typeof row.briefFeedback === 'object' ? row.briefFeedback : null;
const feedbackNotes = String(briefFeedback?.notes || '').trim();
const feedbackEntry = feedbackNotes ? {
  contractVersion: 'operator-brief-feedback-v1',
  notes: feedbackNotes,
  createdAt: briefFeedback.createdAt || new Date().toISOString(),
  appliedTo: 'brief'
} : null;
const feedbackEntrySql = feedbackEntry ? sqlJson(feedbackEntry) : "'null'::jsonb";

if (manualBrief && !feedbackEntry) {
  brief = normalizeBrief(manualBrief, row);
} else {
  provider = 'ai-gateway';
  const gatewayUrl = 'http://ai-gateway:8095/publication-brief';
  const payload = {
    job: {
      publicationJobId: row.publicationJobId,
      avatar: row.avatar,
      avatarDisplayName: row.avatarDisplayName,
      scene: row.scene,
      sceneDisplayName: row.sceneDisplayName,
      format: row.format,
      objective: row.objective,
      businessProfile: row.businessProfile,
      assetType: row.assetType
    },
    currentBrief: feedbackEntry ? (briefFeedback.currentBrief || row.brief || null) : null,
    operatorFeedback: feedbackEntry,
    sceneContext: {
      description: row.sceneDescription,
      visualIntent: row.sceneVisualIntent,
      allowedMood: row.sceneAllowedMood,
      contentAngle: row.sceneContentAngle,
      promptNotes: row.scenePromptNotes
    }
  };

  try {
    const gateway = await this.helpers.httpRequest({
      method: 'POST',
      url: gatewayUrl,
      headers: {
        'Content-Type': 'application/json',
        'X-Request-Id': `publication-brief-${row.publicationJobId}`
      },
      body: payload,
      json: true,
      timeout: 120000
    });

    if (!gateway?.ok || !gateway.brief) {
      const message = gateway?.error || 'AI gateway did not return a publication brief';
      return [{ json: { query: `SELECT false AS ok, ${sql(message)} AS error;` } }];
    }

    brief = normalizeBrief(gateway.brief, row);
    providerMeta = {
      provider: gateway.provider || null,
      model: gateway.model || null,
      requestId: gateway.requestId || null,
      latencyMs: gateway.latencyMs || null
    };
  } catch (error) {
    const message = error?.message || 'AI gateway request failed';
    return [{ json: { query: `SELECT false AS ok, ${sql(message)} AS error;` } }];
  }
}

const query = `
UPDATE publication_jobs
SET
  brief = ${sqlJson(brief)},
  status = 'brief-ready',
  error_message = NULL,
  updated_at = now(),
  metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
    'briefProvider', ${sql(provider)},
    'briefGeneratedAt', now(),
    'briefProviderMeta', ${sqlJson(providerMeta)},
    'lastBriefFeedback', ${feedbackEntrySql},
    'briefFeedbackHistory', COALESCE(metadata->'briefFeedbackHistory', '[]'::jsonb) || CASE WHEN ${feedbackEntrySql} = 'null'::jsonb THEN '[]'::jsonb ELSE jsonb_build_array(${feedbackEntrySql}) END
  )
WHERE publication_job_id = ${sql(row.publicationJobId)}::uuid
RETURNING
  true AS ok,
  publication_job_id AS "publicationJobId",
  avatar,
  scene,
  format,
  objective,
  business_profile AS "businessProfile",
  asset_type AS "assetType",
  status,
  brief,
  created_at AS "createdAt",
  updated_at AS "updatedAt";
`;

return [{ json: { query } }];

const row = $input.first()?.json || {};
if (row.ok === false || row.ok === 'f') {
  return [{ json: { ok: false, error: row.error || 'Publication brief was not generated.' } }];
}
const brief = typeof row.brief === 'string' ? JSON.parse(row.brief) : row.brief;
return [{
  json: {
    ok: true,
    brief,
    job: {
      publicationJobId: row.publicationJobId,
      avatar: row.avatar,
      scene: row.scene,
      format: row.format,
      objective: row.objective,
      businessProfile: row.businessProfile,
      assetType: row.assetType,
      status: row.status,
      brief,
      createdAt: row.createdAt,
      updatedAt: row.updatedAt
    }
  }
}];
